p=Path(__file__).parent;old=Path('/tmp/sirkit_simd_20261022/floyd/bench.cpp');(p/'bench.cpp').write_bytes(old.read_bytes());variants={'baseline':p/'baseline.hpp','control':p/'baseline.hpp','finite':p/'finite.hpp'};modes={'gcc_plain':['g++'],'gcc_native':['g++','-march=native'],'clang_plain':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0'],'clang_native':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0','-march=native']}
