 c,v=cv;cmd=['taskset','-c','8',*modes[c],'-O2','-std=c++23','-DSKIP_RUNTIME_CHECKS','-DFLOYD_SOURCE="'+str(variants[v])+'"',str(p/'bench.cpp'),'-o',str(p/(c+'_'+v))];a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,a.stderr;return dict(mode=c,variant=v,command=cmd,warnings=a.stderr)
